import{_ as e,o,c as i,ag as n}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"Car Wash","description":"","frontmatter":{},"headers":[],"relativePath":"pl/car-wash/index.md","filePath":"pl/car-wash/index.md"}'),t={name:"pl/car-wash/index.md"};function s(r,a,l,c,d,p){return o(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="car-wash" tabindex="-1">Car Wash <a class="header-anchor" href="#car-wash" aria-label="Permalink to &quot;Car Wash&quot;">​</a></h1><p>Wjedź, wybierz program, a pojazd przejedzie przez obracające się szczotki, pianę, łuki płukania i suszarkę parową, a wszyscy w pobliżu zobaczą to samo mycie. Pieszo gracze biorą myjkę ciśnieniową i zmywają brud poziom po poziomie. Każde miejsce rozmieszcza się w grze i każde ustawienie edytuje się w grze.</p><h2 id="funkcje" tabindex="-1">Funkcje <a class="header-anchor" href="#funkcje" aria-label="Permalink to &quot;Funkcje&quot;">​</a></h2><ul><li><strong>Myjnie tunelowe</strong>: szczotki dopasowane do szerokości pojazdu, łuki piany i płukania, suszarka parowa, synchronizowane dla każdego gracza w pobliżu. Zobacz <a href="/pl/car-wash/tunnels">Tunele</a>.</li><li><strong>Programy mycia</strong>: nazwa, cena, prędkość i wykonywane etapy (piana, płukanie, suszenie, wosk). Wosk utrzymuje pojazd w czystości tak długo, jak zechcesz.</li><li><strong>Myjki ciśnieniowe</strong> na dowolnym propie świata z Twojej listy albo na stanowiskach, które sam rozmieścisz, płatne za poziom brudu. Zobacz <a href="/pl/car-wash/pressure-washers">Myjki ciśnieniowe</a>.</li><li><strong>Edytor tuneli w grze</strong>: utwórz tunel tam, gdzie stoisz, albo skopiuj myjnię z podstawowej wersji gry, przesuń każdy element klawiaturą, zapisz.</li><li><strong>Wszystko w <code>/nay</code></strong>: ceny, programy, zniżki dla zawodów, konto płatności, zablokowane klasy pojazdów, blipy z wizualnym wyborem ikony i koloru. Zobacz <a href="/pl/car-wash/settings">Ustawienia</a>.</li><li><strong>Uczciwie i bezpiecznie</strong>: jeden pojazd na tunel, kontrola jazdy pod prąd i zablokowanego przejazdu, płatności i rezerwacja tunelu weryfikowane na serwerze.</li><li><strong>Zniżki dla zawodów</strong> i procent ceny dla każdego tunelu. Gracze płacą gotówką, z banku albo najpierw gotówką, potem z banku.</li><li><strong>Świadomość mapy</strong>: statyczne szczotki z mapy są ukrywane wzdłuż każdego tunelu i wracają po zatrzymaniu zasobu. W Strawberry pliki mapy bez szczotek zastępują domyślną myjnię.</li><li><strong>API HTTP i webhooki</strong>: historia i statystyki myć dla Twojej strony lub bota, wiadomość na Discordzie po każdym myciu. Zobacz <a href="/pl/car-wash/api">API i webhooki</a>.</li><li><strong>Sześć języków</strong>: angielski, francuski, hiszpański, portugalski, polski, niemiecki.</li></ul><h2 id="kompatybilnosc" tabindex="-1">Kompatybilność <a class="header-anchor" href="#kompatybilnosc" aria-label="Permalink to &quot;Kompatybilność&quot;">​</a></h2><ul><li>Frameworki: ESX Legacy, QBCore, QBox, ox_core, wykrywane automatycznie.</li><li>Target (opcjonalnie, dla myjek ciśnieniowych): ox_target lub qb-target. Bez niego gracze używają podpowiedzi klawisza.</li><li>Zależności: oxmysql i <code>nay_lib</code> (dołączony do zakupu).</li></ul><h2 id="wydajnosc" tabindex="-1">Wydajność <a class="header-anchor" href="#wydajnosc" aria-label="Permalink to &quot;Wydajność&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stan</th><th>Klient (resmon)</th></tr></thead><tbody><tr><td>Bezczynność</td><td>0,00 ms</td></tr><tr><td>Mycie pojazdu</td><td>około 0,08 ms</td></tr></tbody></table><p>Zmierzone narzędziem resmon na game build 3751.</p><h2 id="instalacja" tabindex="-1">Instalacja <a class="header-anchor" href="#instalacja" aria-label="Permalink to &quot;Instalacja&quot;">​</a></h2><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span>ensure nay_lib</span></span>
<span class="line"><span>ensure nay_car_wash</span></span></code></pre></div><p>Wszystkie kroki opisuje strona <a href="/pl/getting-started">Pierwsze kroki</a>. Następnie nadaj sobie <code>nay_car_wash.config</code> (lub <code>nay.admin</code>) i otwórz <code>/nay</code>. Dwa tunele są gotowe od razu: Strawberry i Little Seoul.</p>`,12)])])}const w=e(t,[["render",s]]);export{u as __pageData,w as default};
